CREATE SET TABLE MDP01_META.META_TABLE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      table_id INTEGER NOT NULL,      database_id INTEGER NOT NULL,      table_name VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC NOT NULL,      layer_id INTEGER NOT NULL,      table_kind VARCHAR(1) CHARACTER SET LATIN CASESPECIFIC,      request_text CLOB(16777216) CHARACTER SET UNICODE,      area_id INTEGER,      business_object_id INTEGER,      row_count DECIMAL(18,0),      permanent_space DECIMAL(18,0),      temp_space DECIMAL(18,0),      is_historized CHAR(1) CHARACTER SET LATIN CASESPECIFIC DEFAULT 'N',      historization_type VARCHAR(20) CHARACTER SET LATIN CASESPECIFIC,      valid_from_column VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      valid_to_column VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      is_current_column VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      comment_string VARCHAR(2000) CHARACTER SET LATIN CASESPECIFIC,      create_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      last_alter_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6))PRIMARY INDEX ( table_id )UNIQUE INDEX ( database_id ,table_name );